<div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-3"><div><a href="<?php echo e(route('home')); ?>" class="text-decoration-none"><i class="bi bi-arrow-left"></i> Retour</a><h1 class="h3 fw-bold mt-2"><?php echo e($exam->title); ?></h1></div><span class="badge text-bg-dark">30 questions · réussite à 24</span></div><form method="POST" action="<?php echo e(route('exams.submit',$exam)); ?>"><?php echo csrf_field(); ?> <?php $__currentLoopData = $exam->questions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $question): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="card question-card mb-4"><div class="card-body p-4"><div class="d-flex justify-content-between mb-3"><span class="badge bg-danger">Question <?php echo e($question->position); ?>/30</span><span class="text-muted small"><?php echo e(round($question->position/30*100)); ?>%</span></div><div class="progress mb-4"><div class="progress-bar bg-danger" style="width:<?php echo e($question->position/30*100); ?>%"></div></div><?php if($question->audio_path): ?><div class="mb-3"><label class="form-label fw-semibold"><i class="bi bi-volume-up"></i> Écouter la question</label><audio controls class="w-100" src="<?php echo e(str_starts_with($question->audio_path,'http') ? $question->audio_path : asset('storage/'.$question->audio_path)); ?>"></audio></div><?php endif; ?> <?php if($question->image_path): ?><div class="text-center mb-3"><img class="img-fluid rounded" src="<?php echo e(str_starts_with($question->image_path,'http') ? $question->image_path : (str_starts_with($question->image_path,'images/') ? asset($question->image_path) : asset('storage/'.$question->image_path))); ?>" alt="Illustration de la question"></div><?php endif; ?><h2 class="h4 arabic mb-4"><?php echo e($question->question_text); ?></h2><div class="row g-3 arabic"><?php $__currentLoopData = $question->options; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $index=>$option): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="col-md-4"><label class="option d-block"><input class="form-check-input me-2" type="radio" name="answers[<?php echo e($question->id); ?>]" value="<?php echo e($index); ?>" required><span><?php echo e($option); ?></span></label></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div></div></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><div class="text-center pb-4"><button class="btn btn-primary btn-lg px-5" type="submit"><i class="bi bi-send"></i> Terminer l’examen</button></div></form></div>
